export async function consumeRateLimitBucket(
  database: D1Database,
  key: string,
  windowSeconds: number,
) {
  const db = createDb(database);
  const now = Date.now();
  const windowMilliseconds = windowSeconds * 1000;
  const bucketQuery = db
    .insert(rateLimitBuckets)
    .values({
