  if (ownerTeamId) {
    const owner = await database
      .select({ name: teams.name })
      .from(teams)
      .where(eq(teams.id, ownerTeamId))
      .get();
    return { id: ownerTeamId, label: owner?.name ?? ownerTeamId, type: "team" as const };
  }
  throw new ApiError(500);
}

