import { Elysia } from "elysia";

import { type AuthEnvironment, type AuthInstance } from "../auth";
import { ApiError } from "./errors";
import { assertMutationOrigin } from "./http";
import { createAuthorizationRoutes } from "./authorization/routes";
import { createApplicationRoutes } from "./applications/routes";
import { createBootstrapRoutes } from "./bootstrap/routes";
import { createInvitationRoutes } from "./invitations/routes";
import { createServiceAccountRoutes } from "./service-accounts/routes";
import { createSystemRoleRoutes } from "./system-roles/routes";
import { createTeamRoutes } from "./teams/routes";
import { createUserRoutes } from "./users/routes";

export function createApiRoutes(environment: AuthEnvironment, auth: AuthInstance) {
  return new Elysia({ name: "shui-api-routes", normalize: false })
    .error({ ApiError })
    .onBeforeHandle(({ request, set }) => {
      if (["POST", "PUT", "PATCH", "DELETE"].includes(request.method)) {
        assertMutationOrigin(environment, request);
      }
      set.headers["cache-control"] = "no-store";
      set.headers.pragma = "no-cache";
    })
    .onError(({ code, error, set }) => {
      set.headers["cache-control"] = "no-store";
      set.headers.pragma = "no-cache";
      const statusCode =
        error instanceof ApiError ? error.statusCode : code === "VALIDATION" ? 400 : 500;
      set.status = statusCode;
      return {
        error: statusCode >= 500 ? "Request failed." : "The request could not be completed.",
      };
    })
    .use(createAuthorizationRoutes(environment, auth))
    .use(createApplicationRoutes(environment, auth))
    .use(createBootstrapRoutes(environment, auth))
    .use(createInvitationRoutes(environment, auth))
    .use(createUserRoutes(environment, auth))
    .use(createSystemRoleRoutes(environment, auth))
    .use(createTeamRoutes(environment, auth))
    .use(createServiceAccountRoutes(environment, auth));
}
import { and, eq, isNull } from "drizzle-orm";

import { createDb } from "../../../db";
import {
  humanPrincipals,
  principals,
  systemRoleGrants,
  systemRoles,
} from "../../../db/domain-schema";
import { type AuthEnvironment, type AuthInstance } from "../../auth";
import { ApiError } from "../errors";

export type Actor = {
  principalId: string;
  userId: string;
  roleKeys: Set<string>;
};

export const SYSTEM_ROLE_PERMISSIONS = {
  root: ["*"] as const,
  "user-admin": [
    "users:read",
    "users:write",
    "teams:read",
    "teams:write",
    "system-roles:read",
  ] as const,
  "application-admin": [
    "applications:read",
    "applications:write",
    "application-roles:read",
    "application-roles:write",
    "assignments:read",
    "assignments:write",
    "oidc-clients:read",
    "oidc-clients:write",
    "owners:read",
    "service-accounts:read",
    "service-accounts:write",
  ] as const,
};

export type SystemPermission =
  (typeof SYSTEM_ROLE_PERMISSIONS)[keyof typeof SYSTEM_ROLE_PERMISSIONS][number];

export const ADMINISTRATOR_ROLE_KEYS = ["root", "user-admin", "application-admin"] as const;

export type AdminAccess = {
  permissions: SystemPermission[];
};

export async function getActor(auth: AuthInstance, environment: AuthEnvironment, request: Request) {
  const session = await auth.api.getSession({
    headers: request.headers,
    query: { disableCookieCache: true, disableRefresh: true },
  });
  if (!session?.user) throw new ApiError(401);

  const db = createDb(environment.DB);
  const principal = await db
    .select({ principalId: principals.id, userId: humanPrincipals.userId })
    .from(humanPrincipals)
    .innerJoin(principals, eq(principals.id, humanPrincipals.principalId))
    .where(
      and(
        eq(humanPrincipals.userId, session.user.id),
        eq(humanPrincipals.status, "active"),
        eq(humanPrincipals.disabled, false),
        eq(principals.type, "human"),
        eq(principals.status, "active"),
      ),
    )
    .get();
  if (!principal || principal.userId !== session.user.id) throw new ApiError(401);

  const roleRows = await db
    .select({ key: systemRoles.key })
    .from(systemRoleGrants)
    .innerJoin(systemRoles, eq(systemRoles.id, systemRoleGrants.roleId))
    .where(
      and(
        eq(systemRoleGrants.principalId, principal.principalId),
        isNull(systemRoleGrants.revokedAt),
      ),
    )
    .all();

  return {
    principalId: principal.principalId,
    roleKeys: new Set(roleRows.map((row) => row.key)),
    userId: session.user.id,
  } satisfies Actor;
}

export async function requireRole(
  auth: AuthInstance,
  environment: AuthEnvironment,
  request: Request,
  roles: readonly string[],
) {
  const actor = await getActor(auth, environment, request);
  if (!roles.some((role) => actor.roleKeys.has(role))) throw new ApiError(403);
  return actor;
}

export async function requireAdminAccess(
  auth: AuthInstance,
  environment: AuthEnvironment,
  request: Request,
): Promise<AdminAccess> {
  const actor = await getActor(auth, environment, request);
  const hasAdminRole = ADMINISTRATOR_ROLE_KEYS.some((roleKey) => actor.roleKeys.has(roleKey));
  if (!hasAdminRole) throw new ApiError(403);
  const permissions = resolvePermissions(actor.roleKeys);
  return { permissions };
}

export async function requirePermission(
  auth: AuthInstance,
  environment: AuthEnvironment,
  request: Request,
  permission: SystemPermission,
) {
  const actor = await getActor(auth, environment, request);
  if (!resolvePermissions(actor.roleKeys).some((value) => value === "*" || value === permission)) {
    throw new ApiError(403);
  }
  return actor;
}

export function resolvePermissions(roleKeys: Iterable<string>) {
  const permissions = Iterator.from(roleKeys).flatMap<SystemPermission>(
    (roleKey) => SYSTEM_ROLE_PERMISSIONS[roleKey as keyof typeof SYSTEM_ROLE_PERMISSIONS] ?? [],
  );

  return Array.from(new Set(permissions)).sort();
}

