import { and, asc, eq, inArray } from "drizzle-orm";
import { APIError } from "better-auth/api";

import { oauthClientResource } from "../../../db/auth-schema";
import { createDb, type AppDb } from "../../../db";
import {
  applicationOauthClients,
  applicationResources,
  applicationRoles,
  applications,
  humanPrincipals,
  principals,
  serviceAccountApplicationAssignments,
  serviceAccountApplicationRoleGrants,
  serviceAccountOauthClients,
  serviceAccounts,
  teamApplicationAssignments,
  teamApplicationRoleGrants,
  teamMemberships,
  teams,
  userApplicationAssignments,
  userApplicationRoleGrants,
} from "../../../db/domain-schema";
import { type AuthEnvironment } from "../../auth";

type ClaimInput = {
  clientId: string;
  userId?: string | null;
  resources?: string[];
  requireTargetResource: boolean;
};

type PrincipalClaims = {
  principalId: string;
  principalType: "user" | "service-account";
  roles: string[];
  teams: string[];
};

export function getShuiClaimNamespace(environment: Pick<AuthEnvironment, "BETTER_AUTH_URL">) {
  return `${new URL(environment.BETTER_AUTH_URL).origin}/claims/`;
}

function throwOAuthError(error: string, description: string): never {
  throw new APIError("BAD_REQUEST", {
    error,
    error_description: description,
  });
}

async function readManagedClient(database: AppDb, clientId: string) {
  const [humanClient, serviceClient] = await Promise.all([
    database
      .select({
        applicationId: applicationOauthClients.applicationId,
      })
      .from(applicationOauthClients)
      .where(eq(applicationOauthClients.clientId, clientId))
      .get(),
    database
      .select({
        applicationId: serviceAccountOauthClients.applicationId,
        serviceAccountPrincipalId: serviceAccountOauthClients.serviceAccountPrincipalId,
      })
      .from(serviceAccountOauthClients)
      .where(eq(serviceAccountOauthClients.clientId, clientId))
      .get(),
  ]);

  if (humanClient && serviceClient) {
    throwOAuthError("invalid_client", "The OAuth client has multiple Shui owners.");
  }

  const mapping = humanClient
    ? { applicationId: humanClient.applicationId, kind: "human" as const }
    : serviceClient
      ? {
          applicationId: serviceClient.applicationId,
          kind: "service" as const,
          serviceAccountPrincipalId: serviceClient.serviceAccountPrincipalId,
        }
      : null;
  if (!mapping) return null;

  const application = await database
    .select({
      status: applications.status,
      authzVersion: applications.authzVersion,
      resourceIdentifier: applicationResources.resourceIdentifier,
    })
    .from(applications)
    .innerJoin(applicationResources, eq(applicationResources.applicationId, applications.id))
    .where(eq(applications.id, mapping.applicationId))
    .get();
  if (!application) throwOAuthError("invalid_target", "The Application resource is missing.");

  const resources = await database
    .select({ resourceId: oauthClientResource.resourceId })
    .from(oauthClientResource)
    .where(eq(oauthClientResource.clientId, clientId))
    .all();
  if (resources.length !== 1 || resources[0]?.resourceId !== application.resourceIdentifier) {
    throwOAuthError(
      "invalid_target",
      "The OAuth client must have exactly one Application resource.",
    );
  }

  return {
    applicationId: mapping.applicationId,
    authzVersion: Number(application.authzVersion ?? 1),
    kind: mapping.kind,
    resourceIdentifier: application.resourceIdentifier,
    serviceAccountPrincipalId: mapping.serviceAccountPrincipalId,
    status: application.status,
  };
}

function assertTargetResource(resources: string[] | undefined, resourceIdentifier: string) {
  if (resources && !resources.includes(resourceIdentifier)) {
    throwOAuthError("invalid_target", "The OAuth request does not target this Application.");
  }
}

async function readHumanClaims(
  database: AppDb,
  applicationId: string,
  userId: string | null | undefined,
): Promise<PrincipalClaims> {
  if (!userId) throwOAuthError("invalid_grant", "A human principal is required.");

  const principal = await database
    .select({
      principalId: humanPrincipals.principalId,
      principalStatus: principals.status,
      humanStatus: humanPrincipals.status,
      disabled: humanPrincipals.disabled,
    })
    .from(humanPrincipals)
    .innerJoin(principals, eq(principals.id, humanPrincipals.principalId))
    .where(
      and(
        eq(humanPrincipals.userId, userId),
        eq(principals.type, "human"),
        eq(principals.status, "active"),
        eq(humanPrincipals.status, "active"),
        eq(humanPrincipals.disabled, false),
      ),
    )
    .get();
  if (!principal || principal.principalStatus !== "active" || principal.humanStatus !== "active") {
    throwOAuthError("invalid_grant", "The human principal is disabled.");
  }

  const [directAssignment, memberships, directRoles] = await Promise.all([
    database
      .select({ id: userApplicationAssignments.id })
      .from(userApplicationAssignments)
      .where(
        and(
          eq(userApplicationAssignments.applicationId, applicationId),
          eq(userApplicationAssignments.userPrincipalId, principal.principalId),
          eq(userApplicationAssignments.status, "active"),
        ),
      )
      .get(),
    database
      .select({ teamId: teamMemberships.teamId })
      .from(teamMemberships)
      .innerJoin(teams, eq(teams.id, teamMemberships.teamId))
      .where(
        and(eq(teamMemberships.userPrincipalId, principal.principalId), eq(teams.status, "active")),
      )
      .all(),
    database
      .select({ roleKey: applicationRoles.key })
      .from(userApplicationRoleGrants)
      .innerJoin(applicationRoles, eq(applicationRoles.id, userApplicationRoleGrants.roleId))
      .where(
        and(
          eq(userApplicationRoleGrants.applicationId, applicationId),
          eq(userApplicationRoleGrants.userPrincipalId, principal.principalId),
          eq(applicationRoles.applicationId, applicationId),
          eq(applicationRoles.status, "active"),
        ),
      )
      .all(),
  ]);

  const teamIds = memberships.map((membership) => membership.teamId);
  const [teamAssignments, teamRoles] = await Promise.all([
    teamIds.length
      ? database
          .select({ teamId: teamApplicationAssignments.teamId })
          .from(teamApplicationAssignments)
          .where(
            and(
              eq(teamApplicationAssignments.applicationId, applicationId),
              eq(teamApplicationAssignments.status, "active"),
              inArray(teamApplicationAssignments.teamId, teamIds),
            ),
          )
          .all()
      : Promise.resolve([]),
    teamIds.length
      ? database
          .select({ teamId: teamApplicationRoleGrants.teamId, roleKey: applicationRoles.key })
          .from(teamApplicationRoleGrants)
          .innerJoin(applicationRoles, eq(applicationRoles.id, teamApplicationRoleGrants.roleId))
          .where(
            and(
              eq(teamApplicationRoleGrants.applicationId, applicationId),
              eq(applicationRoles.applicationId, applicationId),
              eq(applicationRoles.status, "active"),
              inArray(teamApplicationRoleGrants.teamId, teamIds),
            ),
          )
          .all()
      : Promise.resolve([]),
  ]);

  if (!directAssignment && teamAssignments.length === 0) {
    throwOAuthError("invalid_grant", "The principal is not assigned to this Application.");
  }

  const roles = Array.from(
    new Set([...directRoles.map((role) => role.roleKey), ...teamRoles.map((role) => role.roleKey)]),
  ).sort();
  const relevantTeamIds = new Set([
    ...teamAssignments.map((assignment) => assignment.teamId),
    ...teamRoles.map((role) => role.teamId),
  ]);

  return {
    principalId: principal.principalId,
    principalType: "user",
    roles,
    teams: Array.from(relevantTeamIds).sort(),
  };
}

async function readServiceAccountClaims(
  database: AppDb,
  applicationId: string,
  serviceAccountPrincipalId: string,
): Promise<PrincipalClaims> {
  const principal = await database
    .select({
      principalId: principals.id,
      principalType: principals.type,
      principalStatus: principals.status,
    })
    .from(principals)
    .innerJoin(serviceAccounts, eq(serviceAccounts.principalId, principals.id))
    .where(and(eq(principals.id, serviceAccountPrincipalId), eq(principals.type, "service")))
    .get();
  if (!principal || principal.principalType !== "service") {
    throwOAuthError("invalid_client", "The Service Account does not exist.");
  }
  if (principal.principalStatus !== "active") {
    throwOAuthError("invalid_client", "The Service Account is disabled.");
  }

  const assignment = await database
    .select({ id: serviceAccountApplicationAssignments.id })
    .from(serviceAccountApplicationAssignments)
    .where(
      and(
        eq(serviceAccountApplicationAssignments.applicationId, applicationId),
        eq(
          serviceAccountApplicationAssignments.serviceAccountPrincipalId,
          serviceAccountPrincipalId,
        ),
        eq(serviceAccountApplicationAssignments.status, "active"),
      ),
    )
    .get();
  if (!assignment) {
    throwOAuthError("invalid_grant", "The Service Account is not assigned to this Application.");
  }

  const roles = await database
    .select({ roleKey: applicationRoles.key })
    .from(serviceAccountApplicationRoleGrants)
    .innerJoin(
      applicationRoles,
      eq(applicationRoles.id, serviceAccountApplicationRoleGrants.roleId),
    )
    .where(
      and(
        eq(serviceAccountApplicationRoleGrants.applicationId, applicationId),
        eq(
          serviceAccountApplicationRoleGrants.serviceAccountPrincipalId,
          serviceAccountPrincipalId,
        ),
        eq(applicationRoles.applicationId, applicationId),
        eq(applicationRoles.status, "active"),
      ),
    )
    .orderBy(asc(applicationRoles.key))
    .all();

  return {
    principalId: serviceAccountPrincipalId,
    principalType: "service-account",
    roles: Array.from(new Set(roles.map((role) => role.roleKey))).sort(),
    teams: [],
  };
}

export async function resolveShuiClaims(
  environment: Pick<AuthEnvironment, "BETTER_AUTH_URL" | "DB">,
  input: ClaimInput,
) {
  const database = createDb(environment.DB);
  const managedClient = await readManagedClient(database, input.clientId);
  if (!managedClient) return {};

  assertTargetResource(input.resources, managedClient.resourceIdentifier);
  if (managedClient.status !== "active") {
    throwOAuthError("invalid_target", "The Application is disabled.");
  }
  if (input.requireTargetResource && !input.resources?.length) {
    throwOAuthError("invalid_target", "An Application resource is required.");
  }

  const principal =
    managedClient.kind === "human"
      ? await readHumanClaims(database, managedClient.applicationId, input.userId)
      : await readServiceAccountClaims(
          database,
          managedClient.applicationId,
          managedClient.serviceAccountPrincipalId ?? "",
        );
  const namespace = getShuiClaimNamespace(environment);
  return {
    [`${namespace}application_id`]: managedClient.applicationId,
    [`${namespace}principal_id`]: principal.principalId,
    [`${namespace}principal_type`]: principal.principalType,
    [`${namespace}roles`]: principal.roles,
    [`${namespace}teams`]: principal.teams,
    [`${namespace}authz_version`]: managedClient.authzVersion,
  };
}

export function audienceResources(audience: unknown) {
  if (typeof audience === "string") return [audience];
  if (Array.isArray(audience))
    return audience.filter((value): value is string => typeof value === "string");
  return undefined;
}

import { and, asc, eq } from "drizzle-orm";

import { oauthClient, oauthClientResource } from "../../../db/auth-schema";
import { createDb, type AppDb } from "../../../db";
import {
  applicationResources,
  applications,
  principals,
  serviceAccountOauthClients,
  serviceAccounts,
} from "../../../db/domain-schema";
import { type AuthEnvironment } from "../../auth";
import { applicationAuthzVersionStatement } from "../applications/service";
import { type Actor } from "../authorization/service";
import { ApiError } from "../errors";
import {
  auditStatement,
  auditStatementWhen,
  enforceRateLimit,
  outboxStatement,
  outboxStatementWhen,
  randomToken,
  sha256Base64Url,
} from "../../shared/infrastructure";
import type {
  ServiceAccountCredential,
  ServiceAccountCredentialCreateBody,
  ServiceAccountCredentialRotateBody,
} from "../models";

const SERVICE_ACCOUNT_SCOPES = ["api:read"] as const;

function normalizeName(value: string) {
  const normalized = value.normalize("NFKC").trim();
  if (!normalized || normalized.length > 160) throw new ApiError(400);
  return normalized;
}

function timestamp(value: Date | number | null | undefined) {
  return value instanceof Date ? value.getTime() : Number(value ?? 0);
}

function parseStringArray(value: unknown): string[] {
  if (Array.isArray(value)) return value.filter((item): item is string => typeof item === "string");
  if (typeof value !== "string") return [];
  try {
    const parsed: unknown = JSON.parse(value);
    return Array.isArray(parsed)
      ? parsed.filter((item): item is string => typeof item === "string")
      : [];
  } catch {
    return [];
  }
}

async function readServiceAccount(database: AppDb, principalId: string) {
  const row = await database
    .select({
      principalId: serviceAccounts.principalId,
      status: principals.status,
      name: serviceAccounts.name,
    })
    .from(serviceAccounts)
    .innerJoin(principals, eq(principals.id, serviceAccounts.principalId))
    .where(and(eq(serviceAccounts.principalId, principalId), eq(principals.type, "service")))
    .get();
  if (!row) throw new ApiError(404);
  return row;
}

async function readActiveApplication(database: AppDb, applicationId: string) {
  const row = await database
    .select({
      id: applications.id,
      name: applications.name,
      status: applications.status,
      resourceIdentifier: applicationResources.resourceIdentifier,
    })
    .from(applications)
    .innerJoin(applicationResources, eq(applicationResources.applicationId, applications.id))
    .where(eq(applications.id, applicationId))
    .get();
  if (!row) throw new ApiError(404);
  if (row.status !== "active") throw new ApiError(409);
  return row;
}

async function readCredential(database: AppDb, serviceAccountId: string, clientId: string) {
  const row = await database
    .select({
      serviceAccountId: serviceAccountOauthClients.serviceAccountPrincipalId,
      applicationId: serviceAccountOauthClients.applicationId,
      applicationName: applications.name,
      resourceIdentifier: applicationResources.resourceIdentifier,
      clientId: oauthClient.clientId,
      name: oauthClient.name,
      scopes: oauthClient.scopes,
      disabled: oauthClient.disabled,
      createdAt: oauthClient.createdAt,
      updatedAt: oauthClient.updatedAt,
    })
    .from(serviceAccountOauthClients)
    .innerJoin(oauthClient, eq(oauthClient.clientId, serviceAccountOauthClients.clientId))
    .innerJoin(applications, eq(applications.id, serviceAccountOauthClients.applicationId))
    .innerJoin(
      applicationResources,
      eq(applicationResources.applicationId, serviceAccountOauthClients.applicationId),
    )
    .where(
      and(
        eq(serviceAccountOauthClients.serviceAccountPrincipalId, serviceAccountId),
        eq(serviceAccountOauthClients.clientId, clientId),
      ),
    )
    .get();
  if (!row) throw new ApiError(404);

  const resources = await database
    .select({ resourceId: oauthClientResource.resourceId })
    .from(oauthClientResource)
    .where(eq(oauthClientResource.clientId, clientId))
    .all();
  if (resources.length !== 1 || resources[0]?.resourceId !== row.resourceIdentifier) {
    throw new ApiError(409);
  }

  return {
    serviceAccountId: row.serviceAccountId,
    applicationId: row.applicationId,
    applicationName: row.applicationName,
    resourceIdentifier: row.resourceIdentifier,
    clientId: row.clientId,
    name: row.name ?? row.clientId,
    scopes: parseStringArray(row.scopes),
    disabled: Boolean(row.disabled),
    createdAt: timestamp(row.createdAt),
    updatedAt: timestamp(row.updatedAt),
  } satisfies ServiceAccountCredential;
}

async function insertCredential(
  database: AppDb,
  actor: Actor,
  serviceAccountId: string,
  applicationId: string,
  resourceIdentifier: string,
  name: string,
  requestKind: "created" | "rotated",
  rotatedFromClientId?: string,
) {
  const clientId = `client_${crypto.randomUUID()}`;
  const clientSecret = randomToken();
  const now = Date.now();
  const clientSecretHash = await sha256Base64Url(clientSecret);

  await database.batch([
    database.insert(oauthClient).values({
      id: crypto.randomUUID(),
      clientId,
      clientSecret: clientSecretHash,
      clientDiscoveryId: null,
      disabled: false,
      skipConsent: true,
      enableEndSession: false,
      subjectType: "public",
      scopes: [...SERVICE_ACCOUNT_SCOPES],
      clientCredentialsScopes: [...SERVICE_ACCOUNT_SCOPES],
      userId: null,
      createdAt: new Date(now),
      updatedAt: new Date(now),
      name,
      uri: null,
      icon: null,
      contacts: null,
      tos: null,
      policy: null,
      softwareId: null,
      softwareVersion: null,
      softwareStatement: null,
      redirectUris: [],
      postLogoutRedirectUris: null,
      backchannelLogoutUri: null,
      backchannelLogoutSessionRequired: false,
      tokenEndpointAuthMethod: "client_secret_basic",
      applicationType: "web",
      jwks: null,
      jwksUri: null,
      grantTypes: ["client_credentials"],
      responseTypes: [],
      requirePKCE: false,
      dpopBoundAccessTokens: false,
      referenceId: null,
      metadata: null,
    }),
    database.insert(oauthClientResource).values({
      id: crypto.randomUUID(),
      clientId,
      resourceId: resourceIdentifier,
      metadata: null,
      createdAt: new Date(now),
    }),
    database.insert(serviceAccountOauthClients).values({
      clientId,
      applicationId,
      serviceAccountPrincipalId: serviceAccountId,
      createdAt: now,
      updatedAt: now,
    }),
    applicationAuthzVersionStatement(database, applicationId, now),
    auditStatement(
      database,
      `service-account-credential:${requestKind}:${clientId}`,
      `service_account_credential.${requestKind}`,
      actor.principalId,
      serviceAccountId,
      null,
      {
        applicationId,
        clientId,
        rotatedFromClientId: rotatedFromClientId ?? null,
      },
      now,
    ),
    outboxStatement(
      database,
      `service-account-credential:${requestKind}:outbox:${clientId}`,
      `service_account_credential.${requestKind}`,
      "service_account",
      serviceAccountId,
      { applicationId, clientId, rotatedFromClientId: rotatedFromClientId ?? null },
      now,
    ),
  ]);

  return { clientId, clientSecret };
}

export async function listServiceAccountCredentials(
  environment: AuthEnvironment,
  serviceAccountId: string,
) {
  const database = createDb(environment.DB);
  await readServiceAccount(database, serviceAccountId);
  const rows = await database
    .select({ clientId: serviceAccountOauthClients.clientId })
    .from(serviceAccountOauthClients)
    .where(eq(serviceAccountOauthClients.serviceAccountPrincipalId, serviceAccountId))
    .orderBy(asc(serviceAccountOauthClients.createdAt))
    .all();
  return Promise.all(rows.map((row) => readCredential(database, serviceAccountId, row.clientId)));
}

export async function createServiceAccountCredential(
  environment: AuthEnvironment,
  actor: Actor,
  serviceAccountId: string,
  body: ServiceAccountCredentialCreateBody,
  request: Request,
) {
  await enforceRateLimit(environment, request, "service-account-credential-create", 60, 60);
  const database = createDb(environment.DB);
  const serviceAccount = await readServiceAccount(database, serviceAccountId);
  if (serviceAccount.status !== "active") throw new ApiError(409);
  const application = await readActiveApplication(database, body.applicationId);
  const name = normalizeName(body.name);
  const credential = await insertCredential(
    database,
    actor,
    serviceAccountId,
    application.id,
    application.resourceIdentifier,
    name,
    "created",
  );
  return {
    ...(await readCredential(database, serviceAccountId, credential.clientId)),
    clientSecret: credential.clientSecret,
  };
}

export async function rotateServiceAccountCredential(
  environment: AuthEnvironment,
  actor: Actor,
  serviceAccountId: string,
  clientId: string,
  body: ServiceAccountCredentialRotateBody,
  request: Request,
) {
  await enforceRateLimit(environment, request, "service-account-credential-rotate", 60, 60);
  const database = createDb(environment.DB);
  const serviceAccount = await readServiceAccount(database, serviceAccountId);
  if (serviceAccount.status !== "active") throw new ApiError(409);
  const current = await readCredential(database, serviceAccountId, clientId);
  const application = await readActiveApplication(database, current.applicationId);
  const name = normalizeName(body.name ?? current.name);
  const credential = await insertCredential(
    database,
    actor,
    serviceAccountId,
    application.id,
    application.resourceIdentifier,
    name,
    "rotated",
    current.clientId,
  );
  return {
    ...(await readCredential(database, serviceAccountId, credential.clientId)),
    clientSecret: credential.clientSecret,
  };
}

export async function setServiceAccountCredentialDisabled(
  environment: AuthEnvironment,
  actor: Actor,
  serviceAccountId: string,
  clientId: string,
  disabled: boolean,
  request: Request,
) {
  await enforceRateLimit(
    environment,
    request,
    disabled ? "service-account-credential-disable" : "service-account-credential-enable",
    60,
    60,
  );
  const database = createDb(environment.DB);
  const current = await readCredential(database, serviceAccountId, clientId);
  if (current.disabled === disabled) return current;
  const serviceAccount = await readServiceAccount(database, serviceAccountId);
  if (!disabled && serviceAccount.status !== "active") throw new ApiError(409);
  if (!disabled) await readActiveApplication(database, current.applicationId);

  const now = Date.now();
  const changed = database
    .update(oauthClient)
    .set({ disabled, updatedAt: new Date(now) })
    .where(and(eq(oauthClient.clientId, clientId), eq(oauthClient.disabled, !disabled)))
    .returning({ clientId: oauthClient.clientId });
  const updated = database
    .select({ value: oauthClient.clientId })
    .from(oauthClient)
    .where(
      and(
        eq(oauthClient.clientId, clientId),
        eq(oauthClient.disabled, disabled),
        eq(oauthClient.updatedAt, new Date(now)),
      ),
    );
  const result = await database.batch([
    changed,
    applicationAuthzVersionStatement(database, current.applicationId, now),
    auditStatementWhen(
      database,
      `service-account-credential:${disabled ? "disabled" : "enabled"}:${clientId}:${now}`,
      `service_account_credential.${disabled ? "disabled" : "enabled"}`,
      actor.principalId,
      serviceAccountId,
      null,
      { applicationId: current.applicationId, clientId, disabled },
      now,
      updated,
    ),
    outboxStatementWhen(
      database,
      `service-account-credential:${disabled ? "disabled" : "enabled"}:outbox:${clientId}:${now}`,
      `service_account_credential.${disabled ? "disabled" : "enabled"}`,
